-- Seed: 8 departments and their KRA / KPI list (from the approved KRA files, Oct 2026)
-- Run after schema.sql. Safe to re-run: existing rows are updated.


on conflict (id) do update set kra_no=excluded.kra_no, kra=excluded.kra, kra_weight=excluded.kra_weight, no=excluded.no, text=excluded.text, target=excluded.target, tv=excluded.tv, dir=excluded.dir, freq=excluded.freq, owner=excluded.owner, star=excluded.star;
